namespace Codemaru.Services;

public sealed record GuideFeature(string Icon, string Title, string Description);

public sealed record GuideFaq(string Question, string Answer);

public sealed record ServiceGuideDetails(
    IReadOnlyList<string> Steps,
    IReadOnlyList<GuideFeature> Features,
    IReadOnlyList<GuideFaq> Faqs);

