    public static ServiceGuideDetails Get(string? language, string serviceKey)
    {
        var languageCatalog = Catalog.TryGetValue(language ?? string.Empty, out var localized)
            ? localized
            : Catalog["en"];
        var normalizedKey = serviceKey.Equals("shop", StringComparison.OrdinalIgnoreCase) ? "shopstore" : serviceKey;
        return languageCatalog.TryGetValue(normalizedKey, out var details)
            ? details
            : languageCatalog["cardhybrid"];
    }

    private static IReadOnlyDictionary<string, ServiceGuideDetails> L(params ServiceGuideDetails[] details)
    {
        string[] keys = ["cardhybrid", "wedding", "thankyou", "families", "cctv", "shopstore", "portfolio", "dreamine"];
        if (details.Length != keys.Length)
        {
            throw new InvalidOperationException($"Guide catalog contains {details.Length} services; expected {keys.Length}.");
        }

        return keys.Zip(details, (key, value) => new KeyValuePair<string, ServiceGuideDetails>(key, value))
            .ToDictionary(pair => pair.Key, pair => pair.Value, StringComparer.OrdinalIgnoreCase);
    }

    private static ServiceGuideDetails D(params string[] values)
    {
        if (values.Length != 13)
        {
            throw new InvalidOperationException($"Service guide contains {values.Length} values; expected 13.");
        }

        return new(
            values[..3],
            [new(FeatureIcons[0], values[3], values[4]), new(FeatureIcons[1], values[5], values[6]), new(FeatureIcons[2], values[7], values[8])],
            [new(values[9], values[10]), new(values[11], values[12])]);
    }

